Mesh<Point, double> mesh;
for (RT::Facet_const_iterator f = rt.facets_begin(); f != rt.facets_end(); ++f) {
    RT::Cell_handle c = f->first;
    unsigned k = f->second;

    // Get dual vertex (power center) for this facet
    Point p = rt.dual(c);

    // Check if facet is large enough (using the provided is_large_facet)
    if (!is_large_facet(rt, *f, threshold)) {
        continue;
    }

    // Get the three vertices of the facet
    Point v0 = rt.vertex(c->vertex(k)->vertex_index());
    Point v1 = rt.vertex(c->vertex((k+1)%3)->vertex_index());
    Point v2 = rt.vertex(c->vertex((k+2)%3)->vertex_index());

    // Add the three edges of the facet to the mesh
    mesh.add_edge(v0, v1, 0.0);
    mesh.add_edge(v1, v2, 0.0);
    mesh.add_edge(v2, v0, 0.0);

    // Add the face (power diagram cell) with its area
    double area = CGAL::to_double(CGAL::area(v0, v1, v2));
    mesh.add_face({v0, v1, v2}, area);
}

// Add edges between dual vertices of adjacent facets
for (RT::Facet_const_iterator f = rt.facets_begin(); f != rt.facets_end(); ++f) {
    RT::Cell_handle c = f->first;
    unsigned k = f->second;

    // Get the three adjacent facets
    for (unsigned i = 0; i < 3; ++i) {
        if (i == k) continue;

        RT::Facet_const_iterator neighbor = f;
        ++neighbor;
        if (neighbor == rt.facets_end()) {
            neighbor = rt.facets_begin();
        }

        // Check if the neighbor is valid and adjacent
        if (neighbor->first->vertex(i) == c->vertex((k+1)%3) ||
            neighbor->first->vertex(i) == c->vertex((k+2)%3)) {

            // Get dual vertices
            Point p1 = rt.dual(c);
            Point p2 = rt.dual(neighbor->first);

            // Check if edge is small (using the provided is_small_edge)
            RT::Edge e = rt.edge(c, i, (k+1)%3);
            if (!is_small_edge(rt, e, threshold)) {
                mesh.add_edge(p1, p2, 0.0);
            }
        }
    }
}

return mesh;

